def main():
    root = pathlib.Path(__file__).resolve().parent.parent
    path = root / 'assets' / 'questions' / 'fragen.json'
    data = json.loads(path.read_text(encoding='utf-8'))
    known = {q['frage'] for q in data}
    added = 0
    problems = []
    for exam, topic, frage, richtig, falsch, erkl in Q:
        opts = [richtig, *falsch]
        if len(set(opts)) != len(opts):
            problems.append(('doppelte Antwort', frage))
        if max(len(o) for o in opts) > 44:
            problems.append(('Antwort zu lang', frage, max(opts, key=len)))
        if frage in known:
            continue
        known.add(frage)
        data.append({'pruefung': exam, 'thema': topic, 'frage': frage,
                     'richtig': richtig, 'falsch': falsch, 'erklaerung': erkl})
        added += 1
    for p in problems:
        print('PROBLEM:', *p)
    if problems and '--force' not in sys.argv:
        sys.exit(1)
    path.write_text(json.dumps(data, ensure_ascii=False, indent=1), encoding='utf-8')
    print(f'{added} neue Fragen, gesamt {len(data)} '
          f'(AP1 {sum(q["pruefung"]=="AP1" for q in data)}, AP2 {sum(q["pruefung"]=="AP2" for q in data)})')

if __name__ == '__main__':
    main()
